import re
from pathlib import Path
from collections import Counter


# ----------------- Text normalization -----------------

def normalize_text(text):
    text = re.sub(r"(\d+)\s*\.\s+(\d{2})(?!\d)", r"\1.\2", text)
    text = re.sub(r"(\d+),\s*(\d{2})(?!\d)", r"\1.\2", text)
    return text


# ----------------- Date parsing -----------------

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}


def _norm_year(y):
    if y < 100:
        return 2000 + y if y < 70 else 1900 + y
    return y


def _correct_year(y):
    if 2015 <= y <= 2025:
        return y
    s = str(y)
    for i, ch in enumerate(s):
        if ch == "7":
            cand = int(s[:i] + "1" + s[i + 1:])
            if 2015 <= cand <= 2025:
                return cand
        if ch == "8":
            cand = int(s[:i] + "0" + s[i + 1:])
            if 2015 <= cand <= 2025:
                return cand
    return None


def _valid_date(y, m, d):
    if not (1 <= m <= 12 and 1 <= d <= 31):
        return False
    if m in (4, 6, 9, 11) and d > 30:
        return False
    if m == 2:
        leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
        if d > (29 if leap else 28):
            return False
    return True


def _collect_date_candidates(text):
    out = []
    for m in re.finditer(r"(?<!\d)(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})(?!\d)", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y = _norm_year(y)
        if _valid_date(y, mo, d):
            out.append((m.start(), y, mo, d))
    for m in re.finditer(r"(?<!\w)(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-]+(\d{2,4})(?!\w)", text):
        d = int(m.group(1))
        mon = m.group(2).lower()
        mon = "sept" if mon.startswith("sept") else mon[:3]
        y = int(m.group(3))
        mo = MONTHS.get(mon)
        if mo is None:
            continue
        y = _norm_year(y)
        if _valid_date(y, mo, d):
            out.append((m.start(), y, mo, d))
    for m in re.finditer(r"(?<!\d)(20\d{2})[/\-\.](\d{1,2})[/\-\.](\d{1,2})(?!\d)", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if _valid_date(y, mo, d):
            out.append((m.start(), y, mo, d))
    return out


def _extract_date_one(text):
    cands = _collect_date_candidates(text)
    if not cands:
        return None
    for pos, y, mo, d in cands:
        cy = _correct_year(y)
        if cy is None:
            continue
        return (cy, mo, d)
    return None


def extract_date(text):
    variants = text.split("==VARIANT==")
    results = []
    for v in variants:
        r = _extract_date_one(v)
        if r is not None:
            results.append(r)
    if not results:
        return None
    counter = Counter(results)
    (y, mo, d), _ = counter.most_common(1)[0]
    return f"{y:04d}-{mo:02d}-{d:02d}"


# ----------------- Total parsing -----------------

NUMBER_RE = re.compile(
    r"(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{2})(?![\d])"
)

EXCLUDE_PATTERNS = [
    r"\bSUB[\s\-]?TOTAL\b",
    r"\bSUBTOTAL\b",
    r"\bTAX\b",
    r"\bGST\b",
    r"\bSST\b",
    r"\bDISCOUNT\b",
    r"\bCHANGE\b",
    r"\bCASH\b",
    r"\bTENDERED?\b",
    r"\bPAID\b",
    r"\bPAYMENT\b",
    r"\bSAVINGS?\b",
    r"\bROUNDING\b",
    r"\bROUND\s*A\w{0,4}\b",
    r"\bSERV(?:ICE)?\s*(?:CHG|CHARGE|TAX)\b",
    r"\bSVR\s+TAX\b",
    r"\bGROSS\s+AMT\b",
    r"\bGROSS\s+AMOUNT\b",
    r"\bITEM\s+COUNT\b",
    r"\bTOT\w*\s+QTY\b",
    r"\bTOT\w*\s+QUANTITY\b",
    r"\bTOT\w*\s+ITEMS?\b",
    r"\bQTY\b",
    r"\bQUANTITY\b",
    r"\bCARD\b",
    r"\bVISA\b",
    r"\bMASTER\s*CARD\b",
    r"\bPOINT\b",
    r"\bBALANCE\b",
    r"\bU\s*(?:NIT)?\s*PRICE\b",
    r"\bU\.PRICE\b",
    r"\bS/PRICE\b",
]
EXCLUDE_RE = re.compile("|".join(EXCLUDE_PATTERNS), re.IGNORECASE)


def _normalize_for_exclusion(line):
    s = re.sub(r"\([^)]*\)", " ", line)
    s = re.sub(
        r"(?i)\b(?:incl(?:uded|usive|uding)?|inc)\.?\s*(?:of\s+)?(?:GST|SST|TAX)\b",
        " ",
        s,
    )
    return s


def _is_line_excluded(line):
    s = _normalize_for_exclusion(line)
    return bool(EXCLUDE_RE.search(s))


SECTION_START_RE = re.compile(
    r"(?i)\bGST\s*SUMMARY\b|\bGSTSUMMARY\b|\bTAX\s+CODE\b|\bGST\s+SUMMER\b"
)


def _mark_excluded(lines):
    excluded = [False] * len(lines)
    in_summary = False
    for i, line in enumerate(lines):
        if SECTION_START_RE.search(line):
            in_summary = True
        if in_summary:
            excluded[i] = True
            continue
        if _is_line_excluded(line):
            excluded[i] = True
    return excluded


def _extract_last_number(line):
    nums = NUMBER_RE.findall(line)
    if not nums:
        return None
    val = nums[-1].replace(",", "")
    try:
        return float(val)
    except ValueError:
        return None


PRIORITY_KEYWORDS = [
    [r"\bGRAND\s+TOT\w*"],
    [r"\bTOT\w*\s*:?\s*RM\b"],
    [r"\bTOT\w*\s+AMOUNT\b", r"\bTOT\w*\s+AMT\b", r"\bTOT\w*\s*AMOUN\b"],
    [
        r"\bNETT?\s+TOT\w*",
        r"\bNET\s+AMT\b",
        r"\bNET\s+AMOUNT\b",
        r"\bNET\s+AMOUN\b",
        r"\bTOT\w*\s+DUE\b",
        r"\bAMOUNT\s+DUE\b",
        r"\bAMT\s+DUE\b",
        r"\bBALANCE\s+DUE\b",
        r"\bROUNDED\s+TOT\w*",
        r"\bFINAL\s+TOT\w*",
        r"\bAMT\s+PAYABLE\b",
        r"\bTOT\w*",
        r"\bAMOUNT\b",
        r"\bAMT\b",
    ],
]


def _extract_total_one(text):
    text = normalize_text(text)
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return None, None
    excluded = _mark_excluded(lines)
    for tier_idx, tier in enumerate(PRIORITY_KEYWORDS):
        pat = re.compile("|".join(tier), re.IGNORECASE)
        best = None
        for i, line in enumerate(lines):
            if excluded[i]:
                continue
            if not pat.search(line):
                continue
            val = _extract_last_number(line)
            if val is None and i + 1 < len(lines) and not excluded[i + 1]:
                val = _extract_last_number(lines[i + 1])
            if val is not None:
                best = (i, val)
        if best is not None:
            return tier_idx, best[1]
    return None, None


def extract_total(text):
    variants = text.split("==VARIANT==")
    results = []  # list of (tier, value, variant_idx)
    for idx, v in enumerate(variants):
        tier, val = _extract_total_one(v)
        if val is not None:
            results.append((tier, val, idx))
    if not results:
        return None
    # Pick highest priority tier (lowest index)
    best_tier = min(r[0] for r in results)
    tier_results = [r for r in results if r[0] == best_tier]
    # Majority vote within tier
    vals = [r[1] for r in tier_results]
    counter = Counter(vals)
    most_common = counter.most_common()
    top_count = most_common[0][1]
    tied = [v for v, c in most_common if c == top_count]
    if len(tied) == 1:
        chosen = tied[0]
    else:
        # Tie-break: pick the one from the earliest variant.
        for r in tier_results:
            if r[1] in tied:
                chosen = r[1]
                break
    return f"{chosen:.2f}"


if __name__ == "__main__":
    for p in sorted(Path("/app/workspace/ocr_full").glob("*.txt")):
        text = p.read_text()
        d = extract_date(text)
        t = extract_total(text)
        print(f"{p.stem}: date={d} total={t}")
